@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository repository;
    @InjectMocks
    private OrderService service;

    @Test
    void shouldCreateOrderForAnyValidUser() {
        // Stub: accept any Long userId and any Order object
        when(repository.save(any(Order.class)))
            .thenReturn(new Order(1L, "Laptop", 1200.0));

        var result = service.createOrder(42L, "Laptop", 1200.0);

        assertThat(result.id()).isEqualTo(1L);
        verify(repository).save(any(Order.class)); // Verify with matcher
    }

    @Test
    void shouldApplyDiscountForSpecificCategory() {
        // Mix matchers: both arguments must use matchers
        when(repository.findByCategory(eq("Electronics")))
            .thenReturn(List.of(new Order(1L, "Phone", 800.0)));

        var orders = service.getOrdersByCategory("Electronics");

        assertThat(orders).hasSize(1);
    }
}
