        when(gateway.charge(argThat(order -> 
            order != null && 
            order.total() > 100.0 && 
            order.status() == OrderStatus.PENDING
        ))).thenReturn(new PaymentResult(true, "TXN123"));

        var order = new Order(1L, "Laptop", 1200.0, OrderStatus.PENDING);
        var result = service.processPayment(order);

        assertThat(result.success()).isTrue();
        // Verify the same custom logic
        verify(gateway).charge(argThat(o -> 
            o != null && o.total() > 100.0 && o.status() == OrderStatus.PENDING
        ));
    }
}
