@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @Captor
    private ArgumentCaptor<Order> orderCaptor;  // Cleaner than forClass()
    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldSaveOrderWithCorrectDetails() {
        orderService.placeOrder("Laptop", 1500.00);

        verify(orderRepository).save(orderCaptor.capture());  // Capture the saved order
        Order capturedOrder = orderCaptor.getValue();

        assertThat(capturedOrder.getItem()).isEqualTo("Laptop");
        assertThat(capturedOrder.getAmount()).isEqualTo(1500.00);
        assertThat(capturedOrder.getStatus()).isEqualTo(OrderStatus.PENDING);
        assertThat(capturedOrder.getTimestamp()).isNotNull();  // Verify timestamp was set
    }
}
