@ExtendWith(MockitoExtension.class)
class UserServiceTest {
    @Mock
    private UserRepository userRepository;

    @Test
    void demonstrateMatcherRules() {
        // WRONG: Mixing matcher (anyString) with raw value (25)
        // when(userRepository.findByNameAndAge(anyString(), 25))  // InvalidUseOfMatchersException

        // CORRECT: All matchers - wrap the literal with eq()
        when(userRepository.findByNameAndAge(anyString(), eq(25)))
            .thenReturn(new User("John", 25));

        // CORRECT: All real values - no matchers at all
        when(userRepository.findByNameAndAge("Alice", 30))
            .thenReturn(new User("Alice", 30));

        // CORRECT: Multiple matchers - all arguments are matchers
        when(userRepository.findByNameAndAge(anyString(), anyInt()))
            .thenReturn(new User("Default", 0));
    }
}
