@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;

    // Lambda form - concise for simple logic
    @Test
    void shouldProcessHighValueOrders() {
        when(orderRepository.save(argThat(order -> 
            order != null && order.getAmount() > 1000.0)))
            .thenReturn(new Order("processed"));
    }

    // Class form - reusable, testable, handles null safely
    static class ValidOrderMatcher implements ArgumentMatcher<Order> {
        @Override
        public boolean matches(Order order) {
            if (order == null) return false;  // Always handle null
            return order.getAmount() > 0 
                && order.getStatus() != OrderStatus.CANCELLED
                && order.getCustomerId() != null;
        }
    }

    @Test
    void shouldSaveOnlyValidOrders() {
        verify(orderRepository).save(argThat(new ValidOrderMatcher()));
    }
}
